    return False

def max_value_on_paths(N, grid_values):
    # Initialize the dynamic programming table
    dp = [[0] * N for _ in range(N)]

    # Loop through the grid values and populate the table
    for x, y, value in grid_values:
        dp[y][x] = value

    # Loop through the table and find the maximum sum of values
    max_sum = 0
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue
            max_sum = max(max_sum, dp[i][j], dp[i][j-1] + dp[i-1][j], dp[i-1][j-1] + dp[i][j])

    return max_sum

def find_number_combinations():
    combinations = []
    for i in range(1, 10):
        for j in range(2*i, 10):
            for k in range(3*i, 10):
