def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize a matrix to store the number of chatting pairs that can be separated by adding an aisle in each position
    chatting_matrix = [[0 for _ in range(N + K)] for _ in range(M + L)]

    # Fill the matrix with the number of chatting pairs that can be separated by adding an aisle in each position
    for (Xi, Yi), (Pi, Qi) in chatting_pairs:
        for i in range(Xi, Xi + K + 1):
            for j in range(Yi, Yi + L + 1):
                chatting_matrix[i][j] += 1

    # Initialize variables to store the optimal row and column indices for the aisles
    optimal_row = 0
    optimal_col = 0

    # Iterate over the matrix and find the most effective positions for aisles
    for i in range(M + L):
        for j in range(N + K):
            if chatting_matrix[i][j] == D:
                # If the current position is an effective position for an aisle, update the optimal row and column indices
                optimal_row = i
                optimal_col = j
                break

    # Return the optimal row and column indices as a space-separated string
    return f"{optimal_row} {optimal_col}"

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    :param n: The highest degree of the polynomial.
    :param coeffs: A list of coefficients, starting with the coefficient of the highest degree term.
    :return: The string representation of the polynomial.
    """
    terms = []
    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        term = ""
        if coeff < 0:
            term += "-"
        elif coeff > 1:
            term += str(abs(coeff))
        if i != 0:
            term += "x^" + str(n - i)
        else:
            term += "x" if n == 1 else str(abs(coeff))
        terms.append(term)
    return " ".join(terms)

def decode(encoded, original, message):
    # Build a mapping from encoded letters to their original letters
    mapping = {}
    for i in range(len(original)):
        if encoded[i] not in mapping:
            mapping[encoded[i]] = original[i]
        else:
            return "Failed"

    # Use the mapping to decode the message
    decoded = ""
    for char in message:
        if char in mapping:
            decoded += mapping[char]
        else:
            return "Failed"

    return decoded

def count_coprime_pairs(x0: int, y0: int) -> int:
    count = 0
    for a in range(1, y0 // x0 + 1):
        b = y0 // x0 // a
        if gcd(a, b) == 1:
            if a == b:
                count += 1
            else:
                count += 2
    return count

def gcd(a, b):
    if b == 0:
        return a
    else:
        return gcd(b, a % b)

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def check_scenario(scenario, liar_count, statements, days_of_week):
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    :param scenario: The name of the participant being tested as the potential criminal.
    :param liar_count: A set of names of participants who are assumed to be liars.
    :param statements: A dictionary mapping participant names to lists of their respective statements.
    :param days_of_week: A set of strings representing the days of the week.
    :return: True if the scenario is consistent with the statements, False otherwise.
    """
    # Initialize a dictionary to store the number of statements for each participant
    participant_statement_count = {}

    # Iterate over the statements and count the number of statements for each participant
    for participant, statements in statements.items():
        participant_statement_count[participant] = len(statements)

    # Iterate over the participants and check if the scenario is consistent with their statements
    for participant in statements:
        if participant == scenario:
            # If the participant is the scenario, check if they made any statements
            if participant_statement_count[participant] == 0:
                return False
        else:
            # If the participant is not the scenario, check if they made any statements
            if participant_statement_count[participant] > 0:
                return False

    # If all participants are consistent with the scenario, return True
    return True

def catalan_number(n: int) -> int:
    """
    Calculate the nth Catalan number.

    :param n: The position in the Catalan number sequence to compute (must be non-negative).
    :return: The nth Catalan number.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1
    return sum(catalan_number(i) * catalan_number(n - i - 1) for i in range(n))

