def min_remaining_space(V, n, volumes):
    # Initialize a two-dimensional array to store the maximum volume that can be occupied by any subset of the items
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Initialize the base case
    for i in range(1, n + 1):
        dp[volumes[i - 1]][i] = 1

    # Fill in the rest of the table
    for i in range(1, V + 1):
        for j in range(1, n + 1):
            # If the current item's volume is less than or equal to the current row's capacity,
            # then the maximum volume that can be occupied by any subset of the items is the same as the previous row
            if volumes[j - 1] <= i:
                dp[i][j] = max(dp[i - volumes[j - 1]][j - 1], dp[i][j - 1])
            # Otherwise, the maximum volume that can be occupied by any subset of the items is the same as the previous row
            else:
                dp[i][j] = dp[i][j - 1]

    # Return the difference between the box's total capacity and the maximum volume that can be occupied by any subset of the items
    return V - max(dp[V])
